<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Maze Bot Explorer</title>
<style>
  body { font-family: sans-serif; text-align: center; background: #fafafa; margin: 0; padding: 20px; }
  #maze { margin: 0 auto; width: 600px; height: 600px; border: 2px solid #333; background: #fff; }
  canvas { display: block; }
  .hud { margin: 10px; font-size: 18px; font-weight: bold; }
  button { font-size: 16px; padding: 5px 15px; cursor: pointer; }
</style>
</head>
<body>
  <h2>Maze Bot Explorer</h2>
  <div class="hud">
    <span>Completed: <span id="completed">0</span> / 24</span>
    &nbsp;&nbsp;|&nbsp;&nbsp;
    <span>Timer: <span id="timer">0</span> ticks</span>
    &nbsp;&nbsp;|&nbsp;&nbsp;
    <button id="reset">Reset</button>
  </div>
  <div id="maze">
    <canvas id="mazeCanvas" width="600" height="600"></canvas>
  </div>

<script>
let lastTickTime = performance.now();

function mulberry32(a) {
  return function() {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
}

function passageKey(u, v) {
  let r1 = u.r, c1 = u.c, r2 = v.r, c2 = v.c;
  if (r1 > r2 || (r1 === r2 && c1 > c2)) {
    let tr = r1, tc = c1;
    r1 = r2; c1 = c2;
    r2 = tr; c2 = tc;
  }
  return r1 + ',' + c1 + '-' + r2 + ',' + c2;
}

function generateMaze(rows, cols, rng) {
  let maze = [];
  for (let r = 0; r < rows; r++) {
    let row = [];
    for (let c = 0; c < cols; c++) {
      row.push({n: true, e: true, s: true, w: true});
    }
    maze.push(row);
  }
  let visited = Array.from({length: rows}, () => Array(cols).fill(false));
  let stack = [{r: 0, c: 0}];
  visited[0][0] = true;
  while (stack.length > 0) {
    let curr = stack[stack.length - 1];
    let neighbors = [];
    let dirs = ['n','e','s','w'];
    for (let d of dirs) {
      let nr = curr.r, nc = curr.c;
      if (d === 'n') nr--;
      else if (d === 's') nr++;
      else if (d === 'e') nc++;
      else if (d === 'w') nc--;
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) {
        neighbors.push({r: nr, c: nc, d: d});
      }
    }
    if (neighbors.length > 0) {
      let nxt = neighbors[Math.floor(rng() * neighbors.length)];
      if (nxt.d === 'n') { maze[curr.r][curr.c].n = false; maze[nxt.r][nxt.c].s = false; }
      if (nxt.d === 'e') { maze[curr.r][curr.c].e = false; maze[nxt.r][nxt.c].w = false; }
      if (nxt.d === 's') { maze[curr.r][curr.c].s = false; maze[nxt.r][nxt.c].n = false; }
      if (nxt.d === 'w') { maze[curr.r][curr.c].w = false; maze[nxt.r][nxt.c].e = false; }
      visited[nxt.r][nxt.c] = true;
      stack.push({r: nxt.r, c: nxt.c});
    } else {
      stack.pop();
    }
  }
  return maze;
}

function markDead(bot, u) {
  let k = u.r + ',' + u.c;
  if (!bot.deadSet.has(k)) {
    bot.deadSet.add(k);
    bot.deadEnds.push({r: u.r, c: u.c});
  }
}

function botStep(bot) {
  if (bot.finished) return;
  let u = bot.pos;
  let w = game.walls(u.r, u.c);
  let dirs = ['n','e','s','w'];
  dirs.sort((a,b) => bot.pref[a] - bot.pref[b]);
  let candidates = [];
  for (let d of dirs) {
    if (w[d]) continue;
    let v = {r: u.r, c: u.c};
    if (d === 'n') v.r--;
    else if (d === 's') v.r++;
    else if (d === 'e') v.c++;
    else if (d === 'w') v.c--;
    if (v.r < 0 || v.r >= game.size.rows || v.c < 0 || v.c >= game.size.cols) continue;
    let pKey = passageKey(u, v);
    let count = bot.passCounts[pKey] || 0;
    if (count < 2) {
      candidates.push({d, v, pKey, count});
    }
  }
  let unvisited = candidates.filter(c => !bot.visited.has(c.v.r + ',' + c.v.c));
  let chosen = null;
  if (unvisited.length > 0) {
    chosen = unvisited[0];
  } else if (candidates.length > 0) {
    chosen = candidates[0];
  }
  if (!chosen) return;
  if (unvisited.length === 0) {
    markDead(bot, u);
  }
  bot.passCounts[chosen.pKey] = (bot.passCounts[chosen.pKey] || 0) + 1;
  bot.prev = u;
  bot.pos = chosen.v;
  bot.visited.add(chosen.v.r + ',' + chosen.v.c);
  bot.path.push({r: chosen.v.r, c: chosen.v.c});
  if (bot.pos.r === game.exit.r && bot.pos.c === game.exit.c) {
    bot.finished = true;
    bot.finishTick = game.elapsed;
  }
}

function updateCompleted() {
  let count = game.bots.filter(b => b.finished).length;
  document.getElementById('completed').innerText = count;
  document.getElementById('timer').innerText = game.elapsed;
}

const canvas = document.getElementById('mazeCanvas');
const ctx = canvas.getContext('2d');
const TICK_MS = 40;

function draw() {
  if (!game._maze || game._maze.length === 0) return;
  const cellSize = canvas.width / game.size.cols;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;
  for (let r = 0; r < game.size.rows; r++) {
    for (let c = 0; c < game.size.cols; c++) {
      let w = game.walls(r, c);
      let x = c * cellSize;
      let y = r * cellSize;
      ctx.beginPath();
      if (w.n) { ctx.moveTo(x, y); ctx.lineTo(x + cellSize, y); }
      if (w.e) { ctx.moveTo(x + cellSize, y); ctx.lineTo(x + cellSize, y + cellSize); }
      if (w.s) { ctx.moveTo(x, y + cellSize); ctx.lineTo(x + cellSize, y + cellSize); }
      if (w.w) { ctx.moveTo(x, y); ctx.lineTo(x, y + cellSize); }
      ctx.stroke();
    }
  }
  ctx.fillStyle = 'rgba(0, 255, 0, 0.3)';
  ctx.fillRect(game.spawn.c * cellSize, game.spawn.r * cellSize, cellSize, cellSize);
  ctx.fillStyle = 'rgba(255, 0, 0, 0.3)';
  ctx.fillRect(game.exit.c * cellSize, game.exit.r * cellSize, cellSize, cellSize);

  let now = performance.now();
  let t = Math.min(1, (now - lastTickTime) / TICK_MS);
  for (let bot of game.bots) {
    let r1 = bot.renderPrev.r, c1 = bot.renderPrev.c;
    let r2 = bot.renderCurr.r, c2 = bot.renderCurr.c;
    let r = r1 + (r2 - r1) * t;
    let c = c1 + (c2 - c1) * t;
    let x = (c + 0.5) * cellSize;
    let y = (r + 0.5) * cellSize;
    ctx.beginPath();
    ctx.arc(x, y, Math.max(2, cellSize * 0.25), 0, Math.PI * 2);
    ctx.fillStyle = bot.color;
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

function loop(time) {
  if (time - lastTickTime >= TICK_MS) {
    if (!game.bots.every(b => b.finished)) {
      game.tick(1);
    }
    lastTickTime = time;
  }
  draw();
  requestAnimationFrame(loop);
}

var game = window.game = {
  elapsed: 0,
  size: {rows: 20, cols: 20},
  spawn: {r: 0, c: 0},
  exit: {r: 19, c: 19},
  _maze: [],
  bots: [],
  walls: function(r, c) {
    let cell = game._maze[r][c];
    return {n: cell.n, e: cell.e, s: cell.s, w: cell.w};
  },
  reset: function(seed) {
    if (seed === undefined) seed = Math.floor(Math.random() * 1e9);
    let rng = mulberry32(seed);
    game._maze = generateMaze(game.size.rows, game.size.cols, rng);
    game.elapsed = 0;
    game.bots = [];
    for (let i = 0; i < 24; i++) {
      let botRng = mulberry32(Math.floor(rng() * 1e9));
      let dirs = ['n','e','s','w'];
      for (let j = dirs.length - 1; j > 0; j--) {
        let k = Math.floor(botRng() * (j + 1));
        [dirs[j], dirs[k]] = [dirs[k], dirs[j]];
      }
      let pref = {};
      dirs.forEach((d, idx) => pref[d] = idx);
      game.bots.push({
        pos: {r: game.spawn.r, c: game.spawn.c},
        prev: null,
        path: [{r: game.spawn.r, c: game.spawn.c}],
        deadEnds: [],
        deadSet: new Set(),
        visited: new Set([game.spawn.r + ',' + game.spawn.c]),
        passCounts: {},
        pref: pref,
        finished: false,
        finishTick: null,
        color: `hsl(${(i * 360 / 24)}, 100%, 50%)`,
        renderPrev: {r: game.spawn.r, c: game.spawn.c},
        renderCurr: {r: game.spawn.r, c: game.spawn.c}
      });
    }
    lastTickTime = performance.now();
    updateCompleted();
    draw();
  },
  tick: function(n) {
    for (let i = 0; i < n; i++) {
      if (game.bots.every(b => b.finished)) break;
      game.elapsed++;
      for (let bot of game.bots) {
        bot.renderPrev = {r: bot.pos.r, c: bot.pos.c};
      }
      for (let bot of game.bots) {
        if (!bot.finished) botStep(bot);
      }
      for (let bot of game.bots) {
        if (bot.finished) bot.renderPrev = {r: bot.pos.r, c: bot.pos.c};
        bot.renderCurr = {r: bot.pos.r, c: bot.pos.c};
      }
    }
    lastTickTime = performance.now();
    updateCompleted();
  }
};

document.getElementById('reset').addEventListener('click', function() {
  game.reset();
});

game.reset();
requestAnimationFrame(loop);
</script>
</body>
</html>
